INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_MODERN_ORTHODOX','Modern Eastern Orthodoxy (19th-21st c.)',1800,2025)
INSERT INTO _e VALUES
 ('ENT_ORTH_ATHONITE_ELDERS','The Modern Athonite Elders','Collective','Elder (Geron) hub','Christian/Orthodox','Hesychasm; monastic eldership; the Jesus Prayer','A','Hub for the modern Athonite startsy / gerontes (Mount Athos): Silouan, Joseph the Hesychast, Paisios, Porphyrios, who renewed hesychast prayer and spiritual fatherhood in the 20th c.'),
 ('ENT_ORTH_ROYAL_MARTYRS','The Royal Martyrs (Romanov Passion-Bearers)','Collective','New Martyr / passion-bearer hub','Christian/Orthodox','Passion-bearing; new-martyrdom of the Russian Revolution','A','Collective hub for Tsar Nicholas II and his family, glorified in 2000 by the Moscow Patriarchate as passion-bearers (strastoterptsy) following their 1918 execution at Yekaterinburg.'),
 ('ENT_ORTH_NIKODEMOS_HAGIORITE','Nikodemos the Hagiorite','Saint','Hesychast / compiler','Christian/Orthodox','Hesychasm; spiritual anthology; canon law','A','Athonite monk (1749-1809), co-compiler of the Philokalia with Macarius of Corinth; foundational figure of the modern hesychast revival. Glorified 1955.'),
 ('ENT_ORTH_IGNATIUS_BRIANCHANINOV','Ignatius Brianchaninov','Saint','Hierarch / ascetic writer','Christian/Orthodox','Asceticism; the Jesus Prayer; patristic spirituality','A','Russian bishop (1807-1867), author of The Arena and On the Prayer of Jesus; major modern systematizer of patristic ascetic teaching. Glorified 1988.'),
 ('ENT_ORTH_THEOPHAN_RECLUSE','Theophan the Recluse','Saint','Hierarch / spiritual writer','Christian/Orthodox','Prayer of the heart; spiritual direction; Philokalic translation','A','Russian bishop (1815-1894) who retired into reclusion; translated the Philokalia into Russian (Dobrotolyubie) and wrote extensively on unceasing prayer. Glorified 1988.'),
 ('ENT_ORTH_JOHN_KRONSTADT','John of Kronstadt','Saint','Wonderworker / pastor','Christian/Orthodox','Pastoral ministry; the Eucharist; healing; charity','A','Russian parish priest (1829-1908), famed wonderworker and author of My Life in Christ; renowned for frequent communion and miracles of healing. Glorified 1990.'),
 ('ENT_ORTH_NECTARIOS_AEGINA','Nektarios of Aegina','Saint','Hierarch / wonderworker','Christian/Orthodox','Healing; humility under slander; monastic founding','A','Greek bishop (1846-1920), Metropolitan of Pentapolis, founder of the convent on Aegina; one of the most popular modern Greek wonderworkers and healers. Glorified 1961.'),
 ('ENT_ORTH_SILOUAN_ATHONITE','Silouan the Athonite','Saint','Hesychast / Elder (Geron)','Christian/Orthodox','Hesychasm; the Jesus Prayer; love of enemies; ''Keep your mind in hell''','A','Russian monk of St Panteleimon''s Monastery on Athos (1866-1938); his life and teaching were transmitted by his disciple Sophrony. Glorified 1987.'),
 ('ENT_ORTH_JOSEPH_HESYCHAST','Joseph the Hesychast','Saint','Hesychast / Elder (Geron)','Christian/Orthodox','Hesychasm; noetic prayer; Athonite monastic renewal','A','Athonite elder (1897-1959) whose disciples repopulated many Athonite monasteries; key figure in the 20th-c. hesychast revival. Glorified 2020.'),
 ('ENT_ORTH_LUKE_SIMFEROPOL','Luke of Simferopol (Voino-Yasenetsky)','Saint','New Confessor / hierarch','Christian/Orthodox','Healing; medicine; confession under persecution','A','Russian archbishop and surgeon (1877-1961), Valentin Voino-Yasenetsky, confessor who suffered Soviet imprisonment and exile while practicing surgery. Glorified 1995/2000.'),
 ('ENT_ORTH_MATRONA_MOSCOW','Matrona of Moscow','Saint','Blessed wonderworker','Christian/Orthodox','Healing; clairvoyance; consolation under persecution','A','Blind Russian laywoman (1881-1952), Matrona Nikonova, venerated for healing and spiritual sight during the Soviet era; one of the most popular Russian saints. Glorified 1999/2004.'),
 ('ENT_ORTH_ELIZABETH_FEODOROVNA','Elizabeth Feodorovna','Saint','New Martyr / Grand Duchess','Christian/Orthodox','Charity; monastic foundation; new-martyrdom','A','Grand Duchess Elizabeth (1864-1918), founder of the Martha and Mary Convent; murdered by the Bolsheviks at Alapayevsk. New-martyr glorified 1981 (ROCOR) / 1992 (Moscow).'),
 ('ENT_ORTH_NICHOLAS_II','Tsar Nicholas II','Saint','Passion-bearer / Royal Martyr','Christian/Orthodox','Passion-bearing; Christian rulership','A','Last Russian emperor (1868-1918), executed with his family at Yekaterinburg; glorified as a passion-bearer (strastoterpets) in 2000.'),
 ('ENT_ORTH_ALEXANDRA_FEODOROVNA','Empress Alexandra Feodorovna','Saint','Passion-bearer / Royal Martyr','Christian/Orthodox','Passion-bearing','A','Last Russian empress (1872-1918), wife of Nicholas II; executed at Yekaterinburg and glorified as a passion-bearer in 2000.'),
 ('ENT_ORTH_ALEXEI_TSAREVICH','Tsarevich Alexei','Saint','Passion-bearer / Royal Martyr','Christian/Orthodox','Passion-bearing','A','Heir to the Russian throne (1904-1918), son of Nicholas II; executed at Yekaterinburg and glorified with his family as a passion-bearer in 2000.'),
 ('ENT_ORTH_JOHN_MAXIMOVITCH','John Maximovitch (of Shanghai and San Francisco)','Saint','Hierarch / wonderworker','Christian/Orthodox','Healing; ascetic episcopate; diaspora mission','A','Russian Orthodox bishop (1896-1966) of the diaspora (Shanghai, Western Europe, San Francisco); ascetic wonderworker. Glorified 1994 (ROCOR).'),
 ('ENT_ORTH_MARIA_SKOBTSOVA','Maria Skobtsova (Maria of Paris)','Saint','New Martyr / monastic','Christian/Orthodox','Social charity; new-martyrdom; ministry to the persecuted','A','Russian emigre nun in Paris (1891-1945) who sheltered Jews and others under Nazi occupation; died at Ravensbruck. Glorified 2004 (Ecumenical Patriarchate).'),
 ('ENT_ORTH_NIKOLAI_VELIMIROVIC','Nikolai Velimirovic','Saint','Hierarch / theologian','Christian/Orthodox','Preaching; theology; spiritual writing','A','Serbian bishop (1880-1956), ''the Serbian Chrysostom'', author of the Prologue of Ohrid; imprisoned at Dachau. Glorified 2003 (Serbian Orthodox Church).'),
 ('ENT_ORTH_JUSTIN_POPOVIC','Justin Popovic','Saint','Theologian / confessor','Christian/Orthodox','Dogmatic theology; patristic revival; christocentric spirituality','A','Serbian theologian and archimandrite (1894-1979), author of the Dogmatics of the Orthodox Church and Lives of the Saints; disciple of patristic tradition. Glorified 2010.'),
 ('ENT_ORTH_PAISIOS_ATHONITE','Paisios of Mount Athos','Saint','Elder (Geron) / hesychast','Christian/Orthodox','Spiritual counsel; the Jesus Prayer; discernment','A','Greek Athonite elder (1924-1994), among the most beloved modern startsy; renowned for counsel and discernment. Glorified 2015 (Ecumenical Patriarchate).'),
 ('ENT_ORTH_PORPHYRIOS_KAVSOKALYVIA','Porphyrios of Kavsokalyvia','Saint','Elder (Geron) / hesychast','Christian/Orthodox','Clairvoyance; healing; spiritual counsel','A','Greek elder (1906-1991) of Kavsokalyvia on Athos and later Athens; famed for charismatic gifts of insight and healing. Glorified 2013 (Ecumenical Patriarchate).'),
 ('ENT_ORTH_SOPHRONY_ESSEX','Sophrony of Essex','Saint','Elder (Geron) / hesychast','Christian/Orthodox','Hesychasm; the Jesus Prayer; monastic founding','A','Russian-born archimandrite (1896-1993), disciple and biographer of Silouan the Athonite; founder of the Monastery of St John the Baptist, Essex. Glorified 2019 (Ecumenical Patriarchate).');
