INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_ORTH_SILOUAN_ATHONITE','member_of','ENT_ORTH_ATHONITE_ELDERS','high','Silouan was an Athonite monk of St Panteleimon''s; charter member of the modern Athonite eldership.'),
 ('ENT_ORTH_JOSEPH_HESYCHAST','member_of','ENT_ORTH_ATHONITE_ELDERS','high','Joseph the Hesychast was a foundational 20th-c. Athonite elder whose disciples renewed Athos.'),
 ('ENT_ORTH_PAISIOS_ATHONITE','member_of','ENT_ORTH_ATHONITE_ELDERS','high','Paisios was among the most prominent modern Athonite elders.'),
 ('ENT_ORTH_PORPHYRIOS_KAVSOKALYVIA','member_of','ENT_ORTH_ATHONITE_ELDERS','high','Porphyrios was an Athonite elder of Kavsokalyvia.'),
 ('ENT_ORTH_SOPHRONY_ESSEX','member_of','ENT_ORTH_ATHONITE_ELDERS','high','Sophrony lived on Athos as a hesychast disciple of Silouan before founding his Essex monastery.'),
 ('ENT_ORTH_NICHOLAS_II','member_of','ENT_ORTH_ROYAL_MARTYRS','high','Nicholas II is the principal of the Romanov passion-bearers glorified in 2000.'),
 ('ENT_ORTH_ALEXANDRA_FEODOROVNA','member_of','ENT_ORTH_ROYAL_MARTYRS','high','Empress Alexandra was glorified among the Royal Martyrs in 2000.'),
 ('ENT_ORTH_ALEXEI_TSAREVICH','member_of','ENT_ORTH_ROYAL_MARTYRS','high','Tsarevich Alexei was glorified among the Royal Martyrs in 2000.'),
 ('ENT_ORTH_ROYAL_MARTYRS','reception_of','ENT_JESUS_CHRIST','high','As passion-bearers (strastoterptsy) the Romanovs are venerated for accepting death in imitation of Christ''s passion; passion-bearing is explicitly a reception of Christ''s Passion, not deification.'),
 ('ENT_ORTH_SOPHRONY_ESSEX','taught_by','ENT_ORTH_SILOUAN_ATHONITE','high','Sophrony was the personal disciple and biographer of Silouan the Athonite, whose teaching he transmitted.'),
 ('ENT_ORTH_NIKODEMOS_HAGIORITE','embodies','ENT_MONASTICISM','high','Nikodemos was an Athonite monk whose life embodied hesychast monasticism.'),
 ('ENT_ORTH_NIKODEMOS_HAGIORITE','transmits','ENT_ORTH_UNCREATED_LIGHT','high','As co-compiler of the Philokalia he transmitted the hesychast doctrine of the uncreated light/noetic prayer.'),
 ('ENT_ORTH_THEOPHAN_RECLUSE','transmits','ENT_ORTH_UNCREATED_LIGHT','high','Theophan translated the Philokalia into Russian, transmitting the hesychast tradition of inner light and the prayer of the heart.'),
 ('ENT_ORTH_THEOPHAN_RECLUSE','teaches','ENT_PRAYER','high','Theophan''s principal teaching concerned unceasing prayer and the prayer of the heart.'),
 ('ENT_ORTH_IGNATIUS_BRIANCHANINOV','teaches','ENT_PRAYER','high','Ignatius''s central work, On the Prayer of Jesus, teaches the practice of the Jesus Prayer.'),
 ('ENT_ORTH_IGNATIUS_BRIANCHANINOV','embodies','ENT_MONASTICISM','high','Ignatius was a monastic reformer whose Arena systematizes patristic ascetic life.'),
 ('ENT_ORTH_SILOUAN_ATHONITE','aligned_with','ENT_ORTH_UNCREATED_LIGHT','high','Silouan''s teaching is firmly within the hesychast experience of grace and the uncreated light.'),
 ('ENT_ORTH_SILOUAN_ATHONITE','teaches','ENT_PRAYER','high','Silouan taught the practice of the Jesus Prayer and prayer for the whole world.'),
 ('ENT_ORTH_JOSEPH_HESYCHAST','aligned_with','ENT_ORTH_UNCREATED_LIGHT','high','Joseph the Hesychast taught noetic prayer and the experience of divine grace in the hesychast tradition.'),
 ('ENT_ORTH_PAISIOS_ATHONITE','teaches','ENT_PRAYER','high','Paisios taught the Jesus Prayer and was a renowned counselor on the spiritual life.'),
 ('ENT_ORTH_PORPHYRIOS_KAVSOKALYVIA','patron_of','ENT_HEALING','medium','Porphyrios was widely venerated for charismatic gifts of healing and spiritual insight.'),
 ('ENT_ORTH_SOPHRONY_ESSEX','aligned_with','ENT_ORTH_UNCREATED_LIGHT','high','Sophrony''s theology of personhood and the vision of the uncreated light continues the Palamite hesychast tradition.'),
 ('ENT_ORTH_JOHN_KRONSTADT','patron_of','ENT_HEALING','high','John of Kronstadt was venerated in his lifetime for numerous miracles of healing.'),
 ('ENT_ORTH_JOHN_KRONSTADT','aligned_with','ENT_ORTH_SERAPHIM','medium','John of Kronstadt belongs to the same Russian wonderworker tradition as Seraphim of Sarov.'),
 ('ENT_ORTH_NECTARIOS_AEGINA','patron_of','ENT_HEALING','high','Nektarios of Aegina is one of the most popular modern Greek healing wonderworkers.'),
 ('ENT_ORTH_LUKE_SIMFEROPOL','patron_of','ENT_HEALING','high','Luke (Voino-Yasenetsky) was both a surgeon and venerated healer; patron of physicians and the sick.'),
 ('ENT_ORTH_LUKE_SIMFEROPOL','aligned_with','ENT_ORTH_PANTELEIMON','medium','As a physician-saint Luke continues the tradition of the unmercenary healers such as Panteleimon.'),
 ('ENT_ORTH_MATRONA_MOSCOW','patron_of','ENT_HEALING','high','Matrona of Moscow is venerated principally for healing and consolation.'),
 ('ENT_ORTH_MATRONA_MOSCOW','aligned_with','ENT_ORTH_SERAPHIM','medium','Matrona stands in the Russian wonderworker lineage exemplified by Seraphim of Sarov.'),
 ('ENT_ORTH_JOHN_MAXIMOVITCH','patron_of','ENT_HEALING','medium','John of Shanghai and San Francisco was venerated as an ascetic wonderworker and healer in the diaspora.'),
 ('ENT_ORTH_JOHN_MAXIMOVITCH','embodies','ENT_MONASTICISM','high','John lived a strict ascetic-monastic episcopate.'),
 ('ENT_ORTH_ELIZABETH_FEODOROVNA','embodies','ENT_MONASTICISM','high','Elizabeth founded and led the Martha and Mary Convent, embodying the monastic-diaconal life.'),
 ('ENT_ORTH_ELIZABETH_FEODOROVNA','reception_of','ENT_JESUS_CHRIST','high','As a new-martyr she is venerated for accepting death in imitation of Christ; martyrdom as reception of Christ''s Passion, not deification.'),
 ('ENT_ORTH_MARIA_SKOBTSOVA','reception_of','ENT_JESUS_CHRIST','high','Maria of Paris is venerated as a new-martyr who died at Ravensbruck serving Christ in the persecuted; martyrdom as reception of Christ''s Passion.'),
 ('ENT_ORTH_MARIA_SKOBTSOVA','embodies','ENT_MONASTICISM','medium','Maria was a professed nun who reconceived monasticism as active social charity.'),
 ('ENT_ORTH_NIKOLAI_VELIMIROVIC','teaches','ENT_WISDOM','high','Nikolai Velimirovic, ''the Serbian Chrysostom'', was a major preacher and theological writer.'),
 ('ENT_ORTH_JUSTIN_POPOVIC','teaches','ENT_WISDOM','high','Justin Popovic was a leading 20th-c. dogmatic theologian of the Orthodox Church.'),
 ('ENT_ORTH_JUSTIN_POPOVIC','taught_by','ENT_ORTH_NIKOLAI_VELIMIROVIC','medium','Justin Popovic was a younger associate and spiritual heir of Nikolai Velimirovic within the Serbian Orthodox revival.');
